import pathlib,json,hashlib,base64,re,copy
P=pathlib.Path('docs/iterations/I05/d2-business-carrier-design')
R=pathlib.Path('docs/reviews/I05/d2-business-carrier-design')
g=json.loads((P/'wire-grammar-r2.json').read_text()); old=json.loads((P/'wire-grammar.json').read_text()); a=json.loads((P/'acceptance-r2.json').read_text()); fm=json.loads((P/'field-map-r2.json').read_text()); projection=json.loads((P/'receipt-projection-r2.json').read_text())
def C(v): return json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False).encode('utf-8')
def require(v,why):
 if not v: raise AssertionError(why)
def eq(x,y): return type(x) is type(y) and x==y
def shape(t,v):
 if 'ref' in t:
  d=g['definitions'][t['ref']]; k=d['kind']
  if k=='record':
   require(type(v) is dict and set(v)==set(d['required'])==set(d['fields']),'exact record '+t['ref'])
   for n,f in d['fields'].items(): shape(f['type'],v[n])
  elif k=='union':
   matches=0
   for branch in d['variants']:
    try: shape(branch,v); matches+=1
    except (AssertionError,ValueError,TypeError): pass
   require(matches==1,'unique finite union '+t['ref'])
  elif k=='primitive':
   shape({'type':d['type']},v)
   if 'pattern' in d:require(re.fullmatch(d['pattern'],v) is not None,'finite pattern')
   if 'maxLength' in d:require(len(v)<=d['maxLength'],'finite length')
   if 'minimum' in d:require(v>=d['minimum'],'finite minimum')
   if t['ref']=='Base64':require(base64.b64encode(base64.b64decode(v,validate=True)).decode()==v,'canonical base64')
   if t['ref']=='SafePath':require(v and not v.startswith('/') and all(x not in v for x in ['\\',':','!','\x00','//']) and all(x not in ['','.','..'] and not x.endswith((' ','.')) for x in v.split('/')),'finite safe path syntax only')
  else: raise AssertionError('external strict schema engine intentionally unavailable')
 elif 'nullable' in t:
  if v is not None: shape(t['nullable'],v)
 elif 'array' in t:
  require(type(v) is list,'exact list')
  for x in v:shape(t['array'],x)
 elif 'const' in t: require(eq(v,t['const']),'exact const')
 elif 'enum' in t: require(any(eq(v,x) for x in t['enum']),'exact enum')
 elif 'type' in t:
  typ={'string':str,'integer':int,'boolean':bool,'null':type(None)}[t['type']];require(type(v) is typ,'exact primitive')
  if type(v) is str:v.encode('utf-8')
 else:raise AssertionError('unknown finite type')
def readfiles(case):
 result={}
 for x in case['originalFileRegistry']:
  f=x['file'];shape({'ref':'FileRef'},f);b=base64.b64decode(x['base64'],validate=True);require(len(b)==f['bytes'] and hashlib.sha256(b).hexdigest()==f['sha256'],'full original bytes/SHA');require(f['path'] not in result,'unique file path');result[f['path']]=(f,b)
 return result
def decode_tree(v):
 tag=v['tag']
 if tag=='null':return None
 if tag in ['string','bool']:return v['value']
 if tag=='int':return int(v['decimal'])
 if tag=='list':return [decode_tree(x) for x in v['items']]
 if tag=='map':
  names=[x['name'] for x in v['members']];require(len(names)==len(set(names)),'no duplicate tree keys');return {x['name']:decode_tree(x['value']) for x in v['members']}
 raise AssertionError('this finite fixture does not interpret arbitrary codecs')
roles={'commandContext':'command-context','targetBinding':'target-binding','cancelRequested':'cancel-request','stopping':'stopping','targetTerminated':'target-terminated','readerJoined':'reader-joined','referencesReleased':'references-released','timing':'timing','physicalTicket':'prior-authorization'}
def relationships(case):
 c=case['carrier'];b=case['binding'];run=case['runtimeReceipt']['runs'][0];attempt=c['attemptId'];shape({'ref':'Carrier'},c);shape({'ref':'BusinessValidationBinding'},b)
 require(b['attemptId']==b['receiptRunId']==attempt==run['runId'],'caller original entry identity');require(b['carrier']['path'].endswith('/carrier.json'),'explicit carrier reference');require(b['buildReceipt']==c['negotiation']['buildReceipt'],'same prior build');core=b['attemptCore'];require(core['attemptId']==attempt,'same core attempt')
 require(not(c['signal'] is not None and c['actualExitCode'] is not None),'signal vs exit')
 dispatched=c['lifecycle']['dispatchState']=='dispatched'
 contexts=[x['record']['runId'] for x in c['frames'] if x['parseState']=='parsed' and x['record'] and x['record'].get('kind')=='business-context']
 if not dispatched:
  require(c['observationState']=='not-started' and c['identityAvailability']=='not-dispatched' and c['runId'] is None and c['stdout'] is None and c['stderr'] is None and c['actualExitCode'] is None and c['signal'] is None and core['kind']=='not-dispatched','no dispatch branch')
 elif not contexts:
  require(c['observationState'] in ['incomplete','pre-header-rejected'] and c['identityAvailability']=='unavailable-before-context' and c['runId'] is None and core['kind']=='pre-context-failure' and core['childRunId'] is None,'dispatched before context branch')
  for k in ['stdout','stderr','actualExitCode','signal','firstCollectionFailure']:require(core[k]==c[k],'same actual raw/exit/failure '+k)
  require(c['stdout'] is not None and c['stderr'] is not None and core['headerRange']==c['header']['range'],'dispatched even zero bytes')
 else:require(len(contexts)==1 and c['runId']==contexts[0] and c['identityAvailability']=='observed-context' and core['kind']=='child-context' and core['core']['runId']==contexts[0],'actual accepted child context identity')
 witnesses=c['callerWitnesses'];ids=[x['witnessId'] for x in witnesses];artifactIds=[x['artifactId'] for x in c['artifacts']];require(len(ids)==len(set(ids)) and not set(ids)&set(artifactIds),'disjoint unique namespaces');seen=set();lookup={x['witnessId']:x for x in witnesses};approved=case['binding']['grammarPin']
 for w in witnesses:
  require(w['attemptId']==attempt and w['origin']=='caller-owned-file','caller attempt/origin');require(all(i in seen for i in w['parentWitnessIds']),'no future/dangling/cross-origin parent');seen.add(w['witnessId'])
  if w['verificationState']=='verified':require(w['collectorOwnerPin']==approved and w['layoutPin']==approved,'synthetic external owner/layout assumption only')
 if dispatched:require(set(core['lifecycleWitnessIds'])==set(ids),'complete core witness refs')
 for attr,purpose in roles.items():
  e=c['lifecycle'][attr];state=e['state']
  if state in ['observed','captured-unverified']:
   require(e['value'] is not None and e['witnessIds'],'caller original not hidden in Tree')
   for wid in e['witnessIds']:
    require(wid in lookup,'caller ref resolves correct namespace');w=lookup[wid];require(w['purpose']==purpose,'caller purpose, no request-as-terminated')
    if state=='observed':require(w['verificationState']=='verified' and e['reason'] is None,'no unverified promotion')
  elif state in ['unavailable','not-applicable']:require(e['value'] is None and not e['witnessIds'] and e['reason'] is not None,'explicit unavailable')
  if attr=='targetTerminated' and state=='observed':
   fact=decode_tree(e['value']);require(fact['observation']=='actual-owned-exit' and fact['exitCode']==c['actualExitCode'] and fact['signal']==c['signal'] and fact['ownedTargetWitnessId'] in lookup and lookup[fact['ownedTargetWitnessId']]['purpose']=='target-binding','owned exit not request/terminal')
 return True
def allfiles(case):
 files=readfiles(case);c=case['carrier'];b=case['binding'];receipt=case['runtimeReceipt'];manifest=receipt['runtimeEvidenceManifest'];entry=files[manifest['manifestFile']['path']];require(entry[0]==manifest['manifestFile'],'manifest full identity');m=json.loads(entry[1]);require(m['files']==manifest['files'] and m['complete'] is True,'same full manifest');paths=[x['path'] for x in m['files']];require(len(paths)==len(set(paths)),'unique manifest files');require(set(paths)==set(files)-{manifest['manifestFile']['path']},'no missing original/self/future receipt');require(files[b['carrier']['path']][1]==C(c),'carrier file full original');bf=next(x for x in case['originalFileRegistry'] if x['role']=='complete-binding2');require(files[bf['file']['path']][1]==C(b),'binding full original')
 for f in m['files']:require(files[f['path']][0]==f,'every manifest FileRef full')
 registry=json.loads(files[case['callerAttemptRegistry']['path']][1]);require([x['attemptId'] for x in registry['orderedAttempts']]==[x['runId'] for x in receipt['runs']],'all attempts in original order')
 for w in c['callerWitnesses']:
  require(w['file']['path'] in paths and files[w['file']['path']][0]==w['file'],'caller whole file in manifest');payload=json.loads(files[w['file']['path']][1]);shape({'ref':'CallerWitnessPayload'},payload);require(payload['attemptId']==w['attemptId'] and payload['purpose']==w['purpose'] and w['fieldPointer']=='/value','exact source purpose/pointer')
  for attr in roles:
   e=c['lifecycle'][attr]
   if w['witnessId'] in e['witnessIds']:require(e['value']==payload['value'],'exact complete actual value pointer')
 return True
schema=json.loads((R/'fixed-v3-r2/runtime-validation-receipt.schema.json').read_text());runReq=schema['properties']['runs']['items']['required'];require(len(runReq)==31 and [x['field'] for x in projection['rows']]==runReq,'all31 projection rows');require(projection['schemaChanges']==[],'no schema changes')
for row in projection['rows']:require(row['receivedShape']==schema['properties']['runs']['items']['properties'][row['field']],'exact received full shape')
for case in a['completeSyntheticFailureExamples']:
 relationships(case);allfiles(case);receipt=case['runtimeReceipt'];run=receipt['runs'][0];require(set(receipt)==set(schema['required']) and set(run)==set(runReq),'complete receipt root/run required sets');require(run['runId']==case['carrier']['attemptId'] and type(run['runId']) is str and run['runId'],'caller nonempty run key');require(not run['collectionComplete'] and not run['fullSuiteCollectionComplete'] and run['headerPayload'] is None and not run['moduleLoaders'] and not run['observedPaths'],'no fake collected actuals');require(run['actualExitCode']==case['carrier']['actualExitCode'] and run['signal']==case['carrier']['signal'],'actual exit projection')
 if run['observationState']=='pre-header-rejected':require(run['actualExitCode']==2 and run['failure']['actor']=='probe' and run['headerState']=='absent','CR-R probe rejection')
rows={(x['definition'],x['field']):x for x in fm['fields']};require(len(rows)==len(fm['fields'])==fm['fieldCount'],'unique complete field map');allfields=[]
for n,d in g['definitions'].items():
 if d.get('kind')=='record':
  require(set(d['required'])==set(d['fields']) and len(d['required'])==len(set(d['required'])),'exact record fields')
  for k,v in d['fields'].items():
   x=rows[(n,k)];require(x['type']==v['type'] and x['owner']==v['owner'] and x['meaning']==v['meaning'] and x['relationshipRule']==v['rule'],'all mapped field data');allfields.append((n,k))
require(len(allfields)==len(rows),'no unreferenced map rows');require(g['definitions']['Artifact']==old['definitions']['Artifact'],'original child Artifact untouched')
for n in ['ContextFrame','StageFrame','ObservationFrame','TerminalFrame','EvidenceValue','Piece']:require(g['definitions'][n]==old['definitions'][n],'child frame grammar unchanged '+n)
oldfm=json.loads((P/'field-map.json').read_text())
for k in ['legacyMandatoryMaterialDestinations','fullLegacyFamilies']:require(fm[k]==oldfm[k],'full old material rows unchanged')
base=copy.deepcopy(a['completeSyntheticFailureExamples'][0]);executed=[]
def negative(name,mutate,check=relationships):
 x=copy.deepcopy(base);mutate(x)
 try:check(x)
 except (AssertionError,ValueError,KeyError,TypeError):executed.append(name);return
 raise AssertionError('negative escaped: '+name)
negative('precontext-child-id-invented',lambda x:x['carrier'].update(runId='invented-child'))
negative('attempt-as-child',lambda x:x['carrier'].update(runId=x['carrier']['attemptId']))
negative('dispatch-as-notstarted',lambda x:x['carrier']['lifecycle'].update(dispatchState='not-started'))
negative('raw-file-null-after-dispatch',lambda x:x['carrier'].update(stdout=None))
negative('receipt-null-runid',lambda x:x['runtimeReceipt']['runs'][0].update(runId=None))
negative('receipt-key-not-original-attempt',lambda x:x['runtimeReceipt']['runs'][0].update(runId='invented-entry'))
negative('receipt-child-key-copied',lambda x:x['binding'].update(receiptRunId='child-id'))
negative('failed-attempt-omitted',lambda x:x['runtimeReceipt'].update(runs=[]),allfiles)
