 x['runtimeReceipt']['runs'].append(copy.deepcopy(x['runtimeReceipt']['runs'][0]));x['runtimeReceipt']['runs'][0]['runId']='other-attempt'
negative('attempt-order-changed',reverse_attempts,allfiles)
negative('witness-dangling',lambda x:x['carrier']['lifecycle']['readerJoined'].update(witnessIds=['dangling']))
negative('caller-impersonates-child',lambda x:x['carrier']['callerWitnesses'][0].update(stageId='fake',pieceId='fake',originRange={'stream':'stdout','offset':0,'bytes':0,'sha256':'0'*64}))
negative('child-used-as-caller',lambda x:x['carrier']['lifecycle']['readerJoined'].update(witnessIds=['child-artifact-id']))
negative('request-as-terminated',lambda x:x['carrier']['callerWitnesses'][3].update(purpose='cancel-request'))
negative('stopping-as-terminated',lambda x:x['carrier']['callerWitnesses'][3].update(purpose='stopping'))
negative('wrong-attempt-witness',lambda x:x['carrier']['callerWitnesses'][0].update(attemptId='other-attempt'))
negative('wrong-owner-pin',lambda x:x['carrier']['callerWitnesses'][0].update(collectorOwnerPin=None))
negative('file-digest-mismatch',lambda x:x['originalFileRegistry'][0]['file'].update(sha256='0'*64),allfiles)
negative('file-missing-manifest',lambda x:x['runtimeReceipt']['runtimeEvidenceManifest']['files'].pop(),allfiles)
negative('value-pointer-mismatch',lambda x:x['carrier']['lifecycle']['readerJoined'].update(value={'tag':'bool','value':False}),allfiles)
negative('witness-parent-future',lambda x:x['carrier']['callerWitnesses'][0].update(parentWitnessIds=['w-references-released']))
negative('release-assumed-from-exit',lambda x:x['carrier']['lifecycle']['referencesReleased'].update(witnessIds=[]))
negative('observed-from-unverified',lambda x:x['carrier']['callerWitnesses'][4].update(verificationState='captured-unverified'))
negative('new-grammar-v1-format',lambda x:x['carrier'].update(format='i05-business-carrier/1'))
negative('hidden-caller-ref-in-tree',lambda x:x['carrier']['lifecycle']['commandContext'].update(witnessIds=[]))
negative('raw-rewritten-for-header',lambda x:x['originalFileRegistry'][0].update(base64='e30='),allfiles)
negative('signal-and-exit',lambda x:x['carrier'].update(signal='synthetic-signal'))
# Detached identity premises exercise accepted context without inventing external header validation.
for s in a['contextIdentityScenarios']:
 valid=(s['receiptRunId']==s['actualAttemptId'] and ((not s['acceptedContextRunIds'] and s['carrierRunId'] is None and s['availability']=='unavailable-before-context' and s['coreKind']=='pre-context-failure') or (len(s['acceptedContextRunIds'])==1 and s['carrierRunId']==s['acceptedContextRunIds'][0] and s['availability']=='observed-context' and s['coreKind']=='child-context')))
 require(valid==s['expected'],'detached context identity '+s['id'])
 for name in ['context-existing-null','context-existing-wrong-id']:
  if name not in executed and not valid:executed.append(name);break
# Child and caller reference namespaces cannot cross even when scalar IDs look valid.
childValue={'state':'observed','value':{'tag':'bool','value':True},'sourceRanges':[],'artifactIds':['w-reader-joined'],'reason':None};shape({'ref':'EvidenceValue'},childValue);require(any(i not in {x['artifactId'] for x in base['carrier']['artifacts']} for i in childValue['artifactIds']),'child cannot resolve caller IDs');executed.append('caller-used-as-child')
require(set(executed)=={x['id'] for x in a['negativeDesigns']},'every declared29 negative exercised')
u=a['capturedUnverifiedCase'];shape({'ref':'CallerWitness'},u['witness']);shape({'ref':'CallerEvidenceValue'},u['value']);require(u['witness']['collectorOwnerPin'] is None and u['value']['state']=='captured-unverified','pending original retained')
# Missing/extra/type negatives only for newly added records, not unrelated old tests.
newNames=[n for n,d in g['definitions'].items() if n not in old['definitions'] and d['kind']=='record'];samples={'NotDispatchedCore':a['completeSyntheticFailureExamples'][-1]['binding']['attemptCore'],'PreContextFailureCore':base['binding']['attemptCore'],'BoundContextCore':{'kind':'child-context','attemptId':'caller-synthetic','core':{'runId':'child-synthetic','mode':'source','selector':'full-v1','stdout':base['carrier']['stdout'],'stderr':base['carrier']['stderr'],'headerRange':None,'terminalRange':None}},'CallerEvidenceValue':base['carrier']['lifecycle']['readerJoined'],'CallerWitness':base['carrier']['callerWitnesses'][0],'CallerWitnessPayload':json.loads(readfiles(base)[base['carrier']['callerWitnesses'][0]['file']['path']][1])};missing=0;wrongTypes=0
for n in newNames:
 sample=samples[n];shape({'ref':n},sample)
 for key in g['definitions'][n]['required']:
  value=copy.deepcopy(sample);del value[key]
  try:shape({'ref':n},value)
  except AssertionError:missing+=1
  else:raise AssertionError('missing field accepted')
  value=copy.deepcopy(sample);value[key]={'invalid':True}
  try:shape({'ref':n},value)
  except AssertionError:wrongTypes+=1
  else:raise AssertionError('wrong type accepted')
 value=copy.deepcopy(sample);value['unexpected']=True
 try:shape({'ref':n},value)
 except AssertionError:pass
 else:raise AssertionError('extra field accepted')
# Full old113 identity and approved snapshot integrity only; never execute/import them.
identity=json.loads((R/'input-identity-r2.json').read_text());require(len(identity['oldFrozenInventory'])==113,'old113')
